def _post_json(url, payload, timeout=60):
    data = json.dumps(payload).encode()
    req = urllib.request.Request(
        url, data=data, headers={"Content-Type": "application/json"}
    )
    return json.load(urllib.request.urlopen(req, timeout=timeout))


def _get_json(url, timeout=30):
    return json.load(urllib.request.urlopen(url, timeout=timeout))


def _history_error(entry):
    """Pull the real node error out of a history entry instead of a generic message."""
    try:
        for item in entry.get("status", {}).get("messages", []):
            if (
                isinstance(item, (list, tuple))
                and len(item) >= 2
                and item[0] == "execution_error"
            ):
                d = item[1] or {}
                node = d.get("node_type") or d.get("node_id") or "?"
                msg = (d.get("exception_message") or "").strip().replace("\n", " ")
                return f"{node}: {msg[:400]}"
    except Exception:
        pass
    return "unknown ComfyUI error"


def parse_lora_token(prompt):
    """Extract a 'lora:<name>[:<strength>]' token from the prompt.
    Returns (clean_prompt, lora_dict_or_None, note)."""
    m = re.search(r"lora:([A-Za-z0-9_\-]+)(?::([0-9.]+))?", prompt or "")
    if not m:
        return prompt, None, ""
    clean = (prompt[: m.start()] + prompt[m.end() :]).strip(" ,")
    name = m.group(1).lower()
    key = None
    for k in LORAS:
        if name in k or name in LORAS[k]["file"].lower():
            key = k
            break
    if key is None:
        return (
            clean,
            None,
            f"⚠️ unknown LoRA `{name}` (options: {', '.join(LORAS)}) — ignored.\n\n",
        )
    cfg = dict(LORAS[key])
    cfg["key"] = key
    if m.group(2):
        try:
            cfg["sm"] = max(0.1, min(1.5, float(m.group(2))))
        except Exception:
            pass
    return clean, cfg, ""


