def _extract(messages):
    """Return (prompt_text, image_data_url_or_None) from the last user message."""
    text, image = "", None
    for m in reversed(messages):
        if m.get("role") != "user":
            continue
        c = m.get("content")
        if isinstance(c, str):
            text = c
        elif isinstance(c, list):
            parts = []
            for it in c:
                if it.get("type") == "text":
                    parts.append(it.get("text", ""))
                elif it.get("type") == "image_url":
                    image = it.get("image_url", {}).get("url")
            text = " ".join(parts).strip()
        break
    return text.strip(), image


def _ollama_gen(url, model, instr, timeout=120, options=None):
    opts = {"temperature": 0.8}
    if options:
        opts.update(options)
    payload = {"model": model, "prompt": instr, "stream": False, "options": opts}
    data = json.dumps(payload).encode()
    req = urllib.request.Request(
        url.rstrip("/") + "/api/generate",
        data=data,
        headers={"Content-Type": "application/json"},
    )
    r = json.load(urllib.request.urlopen(req, timeout=timeout))
    return (r.get("response") or "").strip()


def _ollama_prompt(url, model, idea):
    """Ask a local Ollama LLM to expand a short idea into a rich image prompt."""
    instr = (
        "You are an expert image-prompt writer. Expand the user's idea into ONE vivid, "
        "detailed image-generation prompt covering subject, setting, lighting, style, mood and "
        "composition. Output ONLY the prompt text - no preamble, no quotes, no lists.\n\n"
        "Idea: " + idea + "\n\nPrompt:"
    )
    out = _ollama_gen(url, model, instr).strip('"').strip()
    return out or idea


def _split_marked_scenes(text):
    """If the user wrote explicit scene markers (Scene 1:, [Scene 2], Scene 3 -, etc.),
    split on them and return each scene body VERBATIM (preamble before the first marker
    is discarded). Returns a list, or None if fewer than 2 markers are found."""
    if not text:
        return None
    matches = list(
        re.finditer(r"(?im)^\s*(?:\[\s*)?scene\s*(\d+)\s*\]?\s*[:\-.)]\s*", text)
    )
    if len(matches) < 2:
        matches = list(re.finditer(r"(?i)\bscene\s*(\d+)\s*[:\-]\s*", text))
    if len(matches) < 2:
        return None
    scenes = []
    for i, m in enumerate(matches):
        start = m.end()
        end = matches[i + 1].start() if i + 1 < len(matches) else len(text)
        body = text[start:end].strip().strip(".,;-").strip()
        if body:
            scenes.append(body)
    return scenes or None


def _ollama_expand_one(url, model, scene, limit=90):
    """Adapt ONE scene into a single vivid <=limit-word shot: COMPRESS an overloaded scene to
    its single most important continuous action, or EXPAND a sparse one with cinematic detail —
    capturing the essence for a ~5s clip. Keeps output inside the video encoder's budget:
    verifies the word count, condenses once if over, then hard-trims. Strips <think> because
    PROMPT_LLM may be a reasoning model."""

    def _run(instr):
        try:
            return (
                _strip_think(
                    _ollama_gen(
                        url, model, instr, timeout=150, options={"num_ctx": 8192}
                    )
                )
                .strip()
                .strip('"')
                .strip()
            )
        except Exception:
            return ""

    base = (
        "/no_think\n"
        f"Turn the following film scene into ONE vivid, densely-packed sentence of {limit} words or FEWER "
        "for a single ~5-second video shot. JUDGE the scene first: if it crams in TOO MUCH (several events "
        "or complex action that can't fit one short clip), COMPRESS it to the SINGLE most important "
        "continuous action and drop the rest; if it is SPARSE, EXPAND it with cinematic detail (framing, "
        "lighting, colour, lens, mood). Either way, the result is ONE slow continuous action in a consistent "
        "cinematic style that captures the essence. "
        "Output ONLY the sentence — no preamble, no 'Scene' label, no numbering, no quotes.\n\n"
        "Scene: " + scene
    )
    out = _run(base)
    if not out:
        return scene
    # verify: if it blew the budget, condense to the single most important action
    if len(out.split()) > limit:
        c = _run(
            "/no_think\n"
            f"Condense the following into ONE sentence of {limit} words or FEWER, keeping the single most "
            "important continuous action and its key visual details (setting, wardrobe, lighting, style). "
            "Output ONLY the sentence.\n\n" + out
        )
        if c and len(c.split()) <= len(out.split()):
            out = c
    # hard safety net: never let more than `limit` words through to the encoder
    words = out.split()
    if len(words) > limit:
        out = " ".join(words[:limit]).rstrip(",.;:") + "."
    return out or scene


def _ollama_shots(url, model, scene, n=5):
    """Ask the LLM to split a scene into shot prompts. Returns a list of strings."""
    instr = (
        f"You are a film storyboard artist. Break the following scene into exactly {n} distinct shots "
        "that tell the story in order (establishing shot, then closer/action shots, then a closing shot). "
        "FIRST output ONE line in this exact format:\n"
        "ANCHOR: <compact fragment, 25 words max: the main character's appearance and wardrobe plus the "
        "visual style and palette of the whole film - no action, no camera direction>\n"
        "Then for EACH shot output ONE line in this exact format:\n"
        "SHOT: <detailed image-generation prompt - subject, framing, lighting, mood, style>\n"
        "The ANCHOR is prepended to every shot automatically, so shots should refer to the character "
        "briefly (e.g. 'the keeper') instead of re-describing them.\n"
        "Each shot becomes a ~5 second video clip, so give each shot ONE simple continuous action "
        "at a slow, natural pace (e.g. 'slowly turns', 'drifts gently') - never several events in "
        "one shot, and no fast action unless the scene demands it.\n\n"
        "Example ANCHOR (from a different scene):\n"
        "ANCHOR: weathered old lighthouse keeper with a grey beard and yellow oilskin coat, cold blue palette, cinematic film still\n\n"
        "Here are 5 CORRECT example shots (from that same scene), each with the reason it is right:\n"
        "SHOT: wide establishing shot of a lighthouse on a storm-lashed cliff at dusk, waves rolling slowly below, camera drifting gently forward, cold blue palette, cinematic film still\n"
        "(correct: opens wide to establish the scene, has exactly ONE slow camera move, and declares the style tokens every later shot will repeat)\n"
        "SHOT: medium shot of the old keeper climbing the spiral staircase, lantern in hand, moving slowly and steadily, warm flame light flickering on stone, cold blue palette, cinematic film still\n"
        "(correct: exactly ONE continuous subject action with an explicit pace word 'slowly' - not 'climbs, reaches the top, and opens the door')\n"
        "SHOT: close-up of the keeper's weathered hands cupping the lantern flame, the flame swaying gently, shallow depth of field, cold blue palette, cinematic film still\n"
        "(correct: a close-up carries tiny gentle motion only - big actions cannot fit a 5 second close-up)\n"
        "SHOT: low-angle shot inside the lamp room as the great lens begins to glow, its beam sweeping slowly through the rain, steady camera, cold blue palette, cinematic film still\n"
        "(correct: the camera is 'steady' and the motion 'slow' - no speed words like rushing, racing or motion blur)\n"
        "SHOT: final wide shot of the lighthouse beam cutting through the dark storm while the keeper watches from the gallery, camera pulling back gently, cold blue palette, cinematic film still\n"
        "(correct: closes the story by mirroring shot 1's wide framing, ending on ONE gentle pull-back)\n"
        "The (correct: ...) notes are explanations for YOU - never include them in your output.\n\n"
        "Keep a consistent visual style across all shots. Output ONLY the SHOT lines, nothing else.\n\n"
        "Scene: " + scene
    )
    out = _ollama_gen(url, model, instr, timeout=180)
    shots, anchor = [], ""
    for line in out.splitlines():
        line = line.strip().strip("-*").strip()
        if not line:
            continue
        ma = re.match(r"(?:\d+[.)]\s*)?ANCHOR\s*[:\-]\s*(.+)", line, re.IGNORECASE)
        if ma and not anchor:
            anchor = ma.group(1).strip().rstrip(",.")
            continue
        mm = re.match(r"(?:\d+[.)]\s*)?SHOT\s*[:\-]\s*(.+)", line, re.IGNORECASE)
        if mm:
            shots.append(mm.group(1).strip())
        elif re.match(r"\d+[.)]\s+.{20,}", line):
            shots.append(re.sub(r"^\d+[.)]\s+", "", line))
    if anchor:
        # prepend the anchor to every shot so the character/style description
        # reaches BOTH the keyframe model and the video model for every scene
        shots = [s if anchor.lower() in s.lower() else f"{anchor}, {s}" for s in shots]
    return shots[:6] if len(shots) >= 3 else []


def _ollama_film(url, model, scene, n):
    """Ask the LLM for a shot list + voiceover script. Returns (shots, vos)."""
    instr = (
        f"You are a film director. Create a {n}-shot short film from the scene below.\n"
        "FIRST output ONE line in this exact format:\n"
        "ANCHOR: <compact fragment, 25 words max: the main character's appearance and wardrobe plus the "
        "film's visual style and palette - no action, no camera direction>\n"
        f"Then for EACH of the {n} shots output EXACTLY two lines:\n"
        "SHOT: <ONE dense, vivid sentence of 90 words or FEWER — pack in subject, framing, camera, "
        "lighting, mood and a consistent style; describe ONE slow, continuous action, never several events>\n"
        "VO: <one short voiceover sentence, max 18 words, evocative narration that flows shot to shot>\n"
        "The ANCHOR is prepended to every shot automatically, so shots may refer to the character briefly "
        "instead of re-describing them. Keep the SAME main character in every shot unless the scene "
        "explicitly introduces a different one.\n"
        "Keep the SAME visual style across every shot. Output ONLY these lines, nothing else.\n\nScene: "
        + scene
    )
    out = _ollama_gen(url, model, instr, timeout=240)
    shots, vos, anchor = [], [], ""
    for line in out.splitlines():
        line = line.strip().strip("-*#").strip()
        if not line:
            continue
        ma = re.match(
            r"(?:\d+[.)]\s*)?\*{0,2}ANCHOR\*{0,2}\s*[:\-]\s*(.+)", line, re.IGNORECASE
        )
        if ma and not anchor and not shots:
            anchor = ma.group(1).strip().rstrip(",.")
            continue
        ms = re.match(
            r"(?:\d+[.)]\s*)?\*{0,2}SHOT\*{0,2}\s*\d*\s*[:\-]\s*(.*)",
            line,
            re.IGNORECASE,
        )
        mv = re.match(
            r"(?:\d+[.)]\s*)?\*{0,2}(?:VO|VOICEOVER|NARRATION)\*{0,2}\s*\d*\s*[:\-]\s*(.+)",
            line,
            re.IGNORECASE,
        )
        if ms is not None and mv is None:
            shots.append(ms.group(1).strip())  # may be empty ("SHOT 1:" header style)
            vos.append("")
        elif mv is not None and shots:
            vos[len(shots) - 1] = mv.group(1).strip().strip('"')
        elif shots and not shots[-1]:
            shots[-1] = line  # description on the line(s) after a bare "SHOT n:" header

    def _cap90(txt, limit=90):
        w = txt.split()
        return txt if len(w) <= limit else " ".join(w[:limit]).rstrip(",.;:") + "."

    pairs = [(s, v) for s, v in zip(shots, vos) if s]
    shots = [_cap90(p[0]) for p in pairs][:n]
    vos = [p[1] for p in pairs][:n]
    if anchor:
        # prepend the anchor to every shot so the character/style reaches BOTH the
        # keyframe still and the Wan animation for every scene (prevents the
        # "different character every shot" drift)
        shots = [s if anchor.lower() in s.lower() else f"{anchor}, {s}" for s in shots]
    # narration fallback: LLM sometimes skips VO lines — ask for them separately
    if shots and not any(vos):
        try:
            instr2 = (
                "Write one short voiceover sentence (max 18 words) for EACH numbered shot of a short film, "
                "flowing as continuous narration. Output ONLY the sentences, one per line, no numbering.\n\n"
                + "\n".join(f"{i}. {s}" for i, s in enumerate(shots, 1))
            )
            lines = [
                l.strip().strip('"').lstrip("0123456789.)- ").strip()
                for l in _ollama_gen(url, model, instr2, timeout=120).splitlines()
                if l.strip()
            ]
            vos = (lines + [""] * len(shots))[: len(shots)]
        except Exception:
            pass
    return shots, vos


def _strip_think(text):
    """Remove <think>...</think> reasoning blocks. Also drops an UNCLOSED <think>
    (model ran out of context mid-reasoning) so a truncated chain can't poison parsing.
    """
    t = re.sub(r"(?is)<think>.*?</think>", "", text or "")
    t = re.sub(r"(?is)<think>.*$", "", t)  # unclosed think → strip to end
    return t.strip()


def _ollama_produce(url, model, story, maxn=6, secs=5.0, think=True):
    """Big-model PRODUCER pass for Director's Cut: adapt an arbitrary-length story to the
    film engine's hard limits — reason about runtime, then compress or expand to fit,
    choosing the shot count. Returns (shots, vos).

    think=False (default) prepends Qwen3's /no_think switch for a fast, reliable direct
    answer; think=True allows full chain-of-thought (slower, needs more context)."""
    total = int(maxn * secs)
    instr = (
        ("" if think else "/no_think\n")
        + "You are a film PRODUCER and EDITOR adapting a user's story into a short, narrated, "
        "AI-generated film. The rendering engine has HARD limits you MUST respect:\n"
        f"- The film is AT MOST {maxn} shots; each shot becomes a ~{secs:g}-second video clip, so the "
        f"whole film is only about {total} seconds long.\n"
        "- Each shot shows ONLY ONE slow, continuous action or camera move — no fast motion, no "
        "multiple events in a shot, no complex choreography.\n"
        "- Each shot description is ONE vivid sentence of 90 words or fewer (subject, framing, camera, "
        "lighting, mood) and repeats ONE consistent visual style across every shot.\n\n"
        "Think carefully about how much of this story can realistically play out in that runtime, then "
        "ADAPT it: if it is too big, COMPRESS to its essential beats and emotional arc (setup, turn, "
        "payoff); if it is thin, EXPAND with visual detail. Preserve the ESSENCE, tone and most iconic "
        f"moments. Choose the best number of shots between 2 and {maxn}.\n\n"
        "Output the shot list EXACTLY in this format and nothing else — first ONE anchor line:\n"
        "ANCHOR: <compact fragment, 25 words max: the main character's appearance and wardrobe plus the "
        "film's visual style and palette - no action, no camera>\n"
        "then EXACTLY two lines per shot:\n"
        "SHOT: <=90-word vivid visual prompt>\n"
        "VO: <=18-word narration that flows shot to shot>\n"
        "The ANCHOR is prepended to every shot automatically - keep the SAME main character in every "
        "shot unless the story explicitly changes who is on screen.\n\n"
        "Story:\n" + story
    )
    out = _strip_think(
        _ollama_gen(
            url,
            model,
            instr,
            timeout=(1800 if think else 600),
            options={"num_ctx": 16384 if think else 8192},
        )
    )
    shots, vos, anchor = [], [], ""
    for line in out.splitlines():
        line = line.strip().strip("-*#").strip()
        if not line:
            continue
        ma = re.match(
            r"(?:\d+[.)]\s*)?\*{0,2}ANCHOR\*{0,2}\s*[:\-]\s*(.+)", line, re.IGNORECASE
        )
        if ma and not anchor and not shots:
            anchor = ma.group(1).strip().rstrip(",.")
            continue
        ms = re.match(
            r"(?:\d+[.)]\s*)?\*{0,2}SHOT\*{0,2}\s*\d*\s*[:\-]\s*(.*)",
            line,
            re.IGNORECASE,
        )
        mv = re.match(
            r"(?:\d+[.)]\s*)?\*{0,2}(?:VO|VOICEOVER|NARRATION)\*{0,2}\s*\d*\s*[:\-]\s*(.+)",
            line,
            re.IGNORECASE,
        )
        if ms is not None and mv is None:
            shots.append(ms.group(1).strip())
            vos.append("")
        elif mv is not None and shots:
            vos[len(shots) - 1] = mv.group(1).strip().strip('"')
        elif shots and not shots[-1]:
            shots[-1] = line

    def _cap90(txt, limit=90):
        w = txt.split()
        return txt if len(w) <= limit else " ".join(w[:limit]).rstrip(",.;:") + "."

    pairs = [(s, v) for s, v in zip(shots, vos) if s]
    shots = [_cap90(p[0]) for p in pairs][:maxn]
    vos = [p[1] for p in pairs][:maxn]
    if anchor:
        shots = [s if anchor.lower() in s.lower() else f"{anchor}, {s}" for s in shots]
    return shots, vos


