def _pick_image(answer, default):
    a = (str(answer) if answer is not None else "").strip()
    if a.isdigit():
        i = int(a) - 1
        if 0 <= i < len(IMAGE_MENU):
            return IMAGE_MENU[i]
    if a:
        for k, lbl in IMAGE_MENU:
            if a.lower() in lbl.lower() or a.lower() in k.lower():
                return (k, lbl)
    return default


