    def __init__(self):
        self.type = "manifold"
        self.valves = self.Valves()

    def pipes(self):
        return [{"id": k, "name": v["name"]} for k, v in MODELS.items()]

    def _upload_image(self, data_url, fname=None):
        head, b64 = data_url.split(",", 1)
        raw = base64.b64decode(b64)
        if not fname:
            ext = "png"
            if "jpeg" in head or "jpg" in head:
                ext = "jpg"
            fname = f"owui_{uuid.uuid4().hex[:8]}.{ext}"
        boundary = "----owui" + uuid.uuid4().hex
        body = b""
        body += ("--" + boundary + "\r\n").encode()
        body += (
            f'Content-Disposition: form-data; name="image"; filename="{fname}"\r\n'
        ).encode()
        body += b"Content-Type: application/octet-stream\r\n\r\n"
        body += raw + b"\r\n"
        body += ("--" + boundary + "\r\n").encode()
        body += b'Content-Disposition: form-data; name="overwrite"\r\n\r\ntrue\r\n'
        body += ("--" + boundary + "--\r\n").encode()
        req = urllib.request.Request(
            self.valves.COMFYUI_URL + "/upload/image",
            data=body,
            headers={"Content-Type": "multipart/form-data; boundary=" + boundary},
        )
        r = json.load(urllib.request.urlopen(req, timeout=60))
        return r["name"]

    def _input_exists(self, name):
        q = urllib.parse.urlencode({"filename": name, "subfolder": "", "type": "input"})
        try:
            urllib.request.urlopen(
                self.valves.COMFYUI_URL + "/view?" + q, timeout=15
            ).read(1)
            return True
        except Exception:
            return False

    def _run_full(self, workflow, timeout=300):
        """Queue a workflow, wait, return the full outputs dict (with real error messages)."""
        cid = uuid.uuid4().hex
        r = _post_json(
            self.valves.COMFYUI_URL + "/prompt", {"prompt": workflow, "client_id": cid}
        )
        pid = r["prompt_id"]
        t0 = time.time()
        while time.time() - t0 < timeout:
            try:
                h = _get_json(f"{self.valves.COMFYUI_URL}/history/{pid}")
            except Exception:
                time.sleep(2)
                continue
            if pid in h:
                st = h[pid].get("status", {})
                if st.get("completed"):
                    return h[pid]["outputs"]
                if st.get("status_str") == "error":
                    raise RuntimeError(_history_error(h[pid]))
            time.sleep(2)
        raise TimeoutError("generation timed out")

    def _run(self, workflow, out_node, timeout=300):
        outs = self._run_full(workflow, timeout)
        imgs = outs.get(out_node, {}).get("images", [])
        if imgs:
            return imgs[0]
        raise RuntimeError("no image in output")

    def _fetch_b64(self, img):
        q = urllib.parse.urlencode(
            {
                "filename": img["filename"],
                "subfolder": img.get("subfolder", ""),
                "type": img.get("type", "output"),
            }
        )
        raw = urllib.request.urlopen(
            self.valves.COMFYUI_URL + "/view?" + q, timeout=120
        ).read()
        return base64.b64encode(raw).decode()

