    async def _video(self, model_id, prompt, image, ee):
        import asyncio

        async def status(desc, done=False):
            if ee:
                await ee(
                    {"type": "status", "data": {"description": desc, "done": done}}
                )

        seed = uuid.uuid4().int % (2**31)
        if model_id == "wan-i2v":
            image_name = None
            if image:
                image_name = await asyncio.to_thread(self._upload_image, image)
            elif await asyncio.to_thread(self._input_exists, "studio_last.png"):
                image_name = "studio_last.png"
            else:
                return "🎞️ **Wan image→video**: attach an image (or generate one first), plus a prompt describing the motion."
            wf = wf_wan(
                prompt or "smooth cinematic motion", 704, 480, 49, seed, image_name
            )
            title = "🎞️ Wan 2.2 image→video"
        elif model_id == "wan-video":
            wf = wf_wan(prompt, 704, 480, 49, seed)
            title = "🎥 Wan 2.2 text→video"
        else:
            wf = wf_ltx(prompt, VIDEO_NEG, 768, 512, 97, seed)
            title = "🎬 LTX text→video"
        await status(f"{title} — rendering…")
        outs = await asyncio.to_thread(self._run_full, wf, 600)
        webp = outs.get("webp", {}).get("images", [])
        mp4 = outs.get("mp4", {}).get("images", [])
        if not mp4 and not webp:
            raise RuntimeError("no video produced")
        if mp4:
            raw = await asyncio.to_thread(self._fetch_bytes_any, mp4[0])
            name, url = _central_save(raw, "video")
            if url:
                await status(f"✅ {title} done", True)
                return (
                    f"**{title}** · seed `{seed}`\n\n"
                    f"### [▶️ Watch the video ({len(raw) // 1024}KB)]({url})\n\n"
                    f"💾 `E:\\ai\\generated\\{name}` — delete the file to delete the video everywhere."
                )
        # fallback (central folder not mounted): legacy inline webp preview
        await status(f"✅ {title} done", True)
        if webp:
            b64 = await asyncio.to_thread(self._fetch_b64, webp[0])
            return (
                f"**{title}** · seed `{seed}`\n\n![video](data:image/webp;base64,{b64})"
            )
        return f"**{title}** · seed `{seed}` — rendered, but the central folder isn't mounted and no preview was produced; check ComfyUI's output folder."

    async def _interactive_storyboard(self, first_msg, ec, ee, user_id=None):
        """Turn-by-turn wizard: asks for each scene via input dialogs, recaps, takes
        params, confirms, then renders. Scenes are used VERBATIM (add 'expand' to enrich).
        """
        import asyncio

        async def status(desc, done=False):
            if ee:
                await ee(
                    {"type": "status", "data": {"description": desc, "done": done}}
                )

        if ec is None:
            return (
                "🎬 Interactive mode needs the input dialog, which isn't available in this client. "
                "Use the marked form instead: type `Scene 1: … Scene 2: …` then `begin`."
            )

        async def ask(title, message, placeholder=""):
            try:
                r = await ec(
                    {
                        "type": "input",
                        "data": {
                            "title": title,
                            "message": message,
                            "placeholder": placeholder,
                        },
                    }
                )
            except Exception:
                return None
            if isinstance(r, dict):
                r = r.get("value", r.get("data", ""))
            return None if r is None else str(r).strip()

        async def confirm(title, message):
            """OK/Cancel modal → True on OK, False on Cancel/close."""
            try:
                r = await ec(
                    {
                        "type": "confirmation",
                        "data": {"title": title, "message": message},
                    }
                )
            except Exception:
                return False
            if isinstance(r, dict):
                return bool(r.get("value", False))
            return bool(r)

        def _params_of(text):
            t = (text or "").lower()
            eng = secs = None
            mm = re.search(r"\b(ltx|wan)\b", t)
            if mm:
                eng = mm.group(1)
            mm = re.search(r"(\d+(?:\.\d+)?)\s*(?:s\b|sec)", t)
            if mm:
                secs = max(2.0, min(8.0, float(mm.group(1))))
            return eng, secs

        m = re.search(r"(\d+)\s*-?\s*shot|(\d+)", first_msg or "")
        num = next((g for g in (m.groups() if m else []) if g), None) if m else None
        if not num:
            return (
                "🎬 **Interactive mode needs a shot count.**\n\n"
                "Enter the number of shots to pair with it — `interactive-mode N-shot` "
                "(**max 5**). Example: `interactive-mode 4-shot` (add `expand`, `wan`/`ltx`, `Ns` if you like)."
            )
        n = max(2, min(5, int(num)))

        eng0, secs0 = _params_of(first_msg)
        engine = eng0 or (self.valves.STORYBOARD_ENGINE or "wan").strip().lower()
        if engine not in ("wan", "ltx"):
            engine = "wan"
        secs = secs0 or max(2.0, min(8.0, float(self.valves.STORYBOARD_SECONDS)))
        expand = bool(
            re.search(r"\b(expand|enrich|enhance)\b", (first_msg or "").lower())
        )

        # ---- collect scenes (loops on 'change') ----
        scenes = []
        while True:
            scenes = []
            for i in range(1, n + 1):
                ans = await ask(
                    f"Scene {i} of {n}",
                    f"What would you like scene {i} to be?\n(Write it exactly how you want it rendered — this is used verbatim.)",
                    "e.g. a Jack Russell rappels slowly onto a rooftop from a black hawk helicopter",
                )
                if not ans:
                    return "🎬 Interactive storyboard cancelled — no scene entered."
                scenes.append(ans)
            recap = "\n".join(f"{i}. {s}" for i, s in enumerate(scenes, 1))
            if await confirm(
                "Confirm your scenes",
                f"So, {n} scenes:\n\n{recap}\n\nOK to lock these in — Cancel to rewrite them all.",
            ):
                break

        # ---- params + final confirm (loops; 'no'/'change' never delete the storyboard) ----
        while True:
            recap = "\n".join(f"{i}. {s}" for i, s in enumerate(scenes, 1))
            eng_name = "Wan 2.2 (quality)" if engine == "wan" else "LTX (fast)"
            p = await ask(
                "Locked in — set parameters",
                (
                    f"{n} scenes locked. Current: {eng_name} · {secs:g}s each · "
                    f"{'expand (LLM enrich)' if expand else 'verbatim (LLM off)'}.\n\n"
                    "• Type `begin` to render with these.\n"
                    "• Type parameters then begin, e.g. `begin wan 4s expand`.\n"
                    "• Type parameters WITHOUT begin to change settings and re-check.\n"
                    "• Type `change` to rewrite the scenes (keeps your settings)."
                ),
                "begin / begin wan 4s expand / change",
            )
            pl = (p or "").lower()
            if not pl:
                return "🎬 Interactive storyboard cancelled."
            if pl.startswith("change"):
                new = []
                for i in range(1, n + 1):
                    ans = await ask(
                        f"Rewrite scene {i} of {n}",
                        f"New text for scene {i}:",
                        scenes[i - 1],
                    )
                    new.append(ans or scenes[i - 1])
                scenes = new
                continue
            e1, s1 = _params_of(pl)
            if e1:
                engine = e1
            if s1:
                secs = s1
            if re.search(r"\b(expand|enrich|enhance)\b", pl):
                expand = True
            if re.search(r"\b(verbatim|raw)\b", pl):
                expand = False
            if not re.match(r"^\s*(begin|start|render|go)\b", pl):
                continue  # params only -> re-show the recap/settings
            eng_name = "Wan 2.2 (quality)" if engine == "wan" else "LTX (fast)"
            if await confirm(
                "Final check — 100% happy?",
                (
                    f"About to render:\n\n{recap}\n\n"
                    f"{n} scenes × {secs:g}s · {eng_name} · "
                    f"{'expand' if expand else 'verbatim'}.\n\n"
                    "OK to start rendering — Cancel to go back to settings."
                ),
            ):
                break
            # Cancel -> back to params loop; storyboard intact

        shots = list(scenes)
        if expand:
            await status(f"🧠 Enriching {n} scene(s) individually…")
            out = []
            for i, sc in enumerate(shots, 1):
                await status(f"🧠 Enriching scene {i}/{n}…")
                out.append(
                    await asyncio.to_thread(
                        _ollama_expand_one,
                        self.valves.OLLAMA_URL,
                        self.valves.PROMPT_LLM,
                        sc,
                    )
                )
            shots = out
        passes = await self._ask_passes(ec)
        last = ""
        for p in range(1, passes + 1):
            if passes > 1 and ee:
                await ee(
                    {
                        "type": "message",
                        "data": {
                            "content": f"### 🎬 Generating video {p} of {passes}\n\n"
                        },
                    }
                )
            last = await self._render_shots(shots, n, secs, engine, False, ee, user_id)
            if passes > 1 and p < passes and ee:
                await ee({"type": "message", "data": {"content": last + "\n\n---\n\n"}})
        return last

    async def _ask_passes(self, ec):
        """MANDATORY gate asked after everything is locked in: how many complete videos to
        generate. Each pass is a full separate render with fresh seeds. Returns 1–4."""
        if ec is None:
            return 1
        try:
            r = await ec(
                {
                    "type": "input",
                    "data": {
                        "title": "How many passes?",
                        "message": (
                            "How many complete videos should I generate? Each pass is a full separate "
                            "render with fresh seeds — go make a cuppa and pick your favourite. (1–4)"
                        ),
                        "placeholder": "1",
                    },
                }
            )
        except Exception:
            return 1
        if isinstance(r, dict):
            r = r.get("value", r.get("data", ""))
        m = re.search(r"\d+", str(r if r is not None else "1"))
        return max(1, min(4, int(m.group(0)))) if m else 1

    def _storyboard_help(self):
        return (
            "🎬 **Storyboard — command reference**\n\n"
            "| Command | What it does |\n|---|---|\n"
            "| `Scene 1: … Scene 2: …` → `begin` | Render your scenes **verbatim** — LLM off, no rewriting |\n"
            "| `begin expand` | Enrich each scene individually (LLM adds detail, never merges) |\n"
            "| `interactive-mode N-shot` | **Turn-by-turn wizard** — I ask you scene by scene (2–5 shots) |\n"
            "| `begin 4s` | Seconds per scene (2–8) |\n"
            "| `begin ltx` / `begin wan` | Fast (LTX) vs quality (Wan 2.2) engine |\n"
            "| `begin stills only` | Classic still image board (no video) |\n"
            "| `hello` / `help` | Show this table |\n\n"
            "**Combine freely:** `begin expand 4s ltx`.\n\n"
            "**Two ways to give scenes:**\n"
            "1. **Marked** — type `Scene 1: …`, `Scene 2: …` in one message, then `begin`. Your wording is used exactly.\n"
            "2. **Interactive** — `interactive-mode 4-shot`, and I'll ask you for each scene one at a time, "
            "recap, take parameters, and confirm before rendering.\n\n"
            "In the wizard you can answer `yes` / `change`, then `begin [params]`, then `confirm` / `no`."
        )

    async def _storyboard(self, scene, ee, user_id=None, messages=None, ec=None):
        import asyncio

        async def status(desc, done=False):
            if ee:
                await ee(
                    {"type": "status", "data": {"description": desc, "done": done}}
                )

        async def emit(md):
            if ee:
                await ee({"type": "message", "data": {"content": md}})

        _low = (scene or "").strip().lower()
        if _low in ("hello", "hi", "help", "?", "commands", "menu"):
            return self._storyboard_help()
        if re.match(r"^\s*interactive(?:[-_\s]?mode)?\b", _low):
            return await self._interactive_storyboard(scene, ec, ee, user_id)

        if not scene:
            return self._storyboard_help()

        def _tokens(text, n, secs, engine, stills):
            """Pull control tokens out of a message; returns updated settings."""
            t = (text or "").lower()
            if any(
                k in t
                for k in ("stills only", "images only", "no video", "still storyboard")
            ):
                stills = True
            mm = re.search(r"(\d+)\s*-?\s*(?:shot|scene)", t)
            if mm:
                n = max(2, min(8, int(mm.group(1))))
            mm = re.search(r"(\d+(?:\.\d+)?)\s*(?:s\b|sec\b|second)", t)
            if mm:
                secs = max(2.0, min(8.0, float(mm.group(1))))
            mm = re.search(r"\b(ltx|wan)\b", t)
            if mm:
                engine = mm.group(1)
            return n, secs, engine, stills

        def _msg_text(c):
            if isinstance(c, str):
                return c
            if isinstance(c, list):
                return " ".join(
                    x.get("text", "")
                    for x in c
                    if isinstance(x, dict) and x.get("type") == "text"
                ).strip()
            return ""

        # defaults from valves
        n = max(2, min(8, int(self.valves.STORYBOARD_SHOTS)))
        secs = max(2.0, min(8.0, float(self.valves.STORYBOARD_SECONDS)))
        engine = (self.valves.STORYBOARD_ENGINE or "wan").strip().lower()
        if engine not in ("wan", "ltx"):
            engine = "wan"
        stills_only = False

        is_begin = bool(
            re.match(r"^\s*(begin|start|render|go)\b", scene.strip().lower())
        )
        if is_begin:
            # settings: earlier scene message first, then the begin line overrides
            begin_line = scene
            scene = ""
            for m in reversed((messages or [])[:-1]):
                if m.get("role") != "user":
                    continue
                txt = _msg_text(m.get("content")).strip()
                if txt and not re.match(r"^\s*(begin|start|render|go)\b", txt.lower()):
                    scene = txt
                    break
            if not scene:
                return "🎬 I don't have a scene yet — describe the story first, then send `begin`."
            n, secs, engine, stills_only = _tokens(scene, n, secs, engine, stills_only)
            n, secs, engine, stills_only = _tokens(
                begin_line, n, secs, engine, stills_only
            )
            expand = bool(
                re.search(
                    r"\b(expand|enrich|enhance)\b", (scene + " " + begin_line).lower()
                )
            )
        else:
            n, secs, engine, stills_only = _tokens(scene, n, secs, engine, stills_only)
            expand = bool(re.search(r"\b(expand|enrich|enhance)\b", scene.lower()))
            if self.valves.STORYBOARD_CONFIRM:
                marked_preview = _split_marked_scenes(scene)
                if marked_preview:
                    n = len(marked_preview)
                eng_name = "Wan 2.2 (quality)" if engine == "wan" else "LTX (fast)"
                mode = (
                    "expand each scene (LLM enrich · never merges)"
                    if expand
                    else "verbatim · LLM OFF"
                )
                est = (
                    n * (20 * secs + 12) + 30
                    if engine == "wan"
                    else n * (6 * secs + 15) + 20
                )
                plan = (
                    f"{n} stills"
                    if stills_only
                    else f"{n} scenes × {secs:g}s · {eng_name} · {mode} · est. ~{max(1, int(est // 60))} min"
                )
                if marked_preview:
                    scene_block = "\n".join(
                        f"> **Scene {i}:** {s}" for i, s in enumerate(marked_preview, 1)
                    )
                else:
                    clean = re.sub(r"\b\d+\s*-?\s*(?:shot|scene)s?\b", "", scene)
                    clean = re.sub(
                        r"\b\d+(?:\.\d+)?\s*(?:s\b|sec\b|seconds?\b)", "", clean
                    )
                    clean = re.sub(r"\s{2,}", " ", clean).strip(" ,.-")
                    scene_block = (
                        f"*{clean[:400]}*\n\n"
                        f"_No explicit `Scene N:` markers found — the LLM will auto-split this into {n} shots. "
                        f"Add `Scene 1:` / `Scene 2:` markers to use your exact wording instead._"
                    )
                return (
                    f"🎬 **Storyboard — ready when you are**\n\n"
                    f"{scene_block}\n\n"
                    f"**Plan:** {plan}\n\n"
                    f"| Command | Effect |\n|---|---|\n"
                    f"| `begin` | ▶️ Render exactly as shown above |\n"
                    f"| `begin expand` | Let the LLM enrich each scene (keeps your words, never merges) |\n"
                    f"| `begin 4s` | Seconds per scene (2–8) |\n"
                    f"| `begin ltx` / `begin wan` | Fast vs quality engine |\n"
                    f"| `begin stills only` | Classic image board (no video) |\n\n"
                    f"Commands combine — e.g. `begin expand 4s ltx`. "
                    f"With `Scene N:` markers your wording is used **verbatim** and the shot-splitter LLM stays "
                    f"**off** unless you add `expand`. Send a new description to replace the scene. "
                    f"*(Menu off via the `STORYBOARD_CONFIRM` valve.)*"
                )

        # 1) build the shot list.
        # If the user wrote explicit "Scene N:" markers we use their wording VERBATIM and
        # keep the shot-splitter LLM OFF — this is the whole point: no re-authoring, no
        # truncation, exactly the scenes and count you typed. Only freeform input (no
        # markers) is auto-split by the LLM. `expand` enriches each scene individually.
        marked = _split_marked_scenes(scene)
        if marked:
            shots = [s.strip() for s in marked][:8]
            n = len(shots)
            if expand:
                await status(
                    f"🧠 Enriching {n} scene(s) individually — verbatim-safe, no merging…"
                )
                out = []
                for i, sc in enumerate(shots, 1):
                    await status(f"🧠 Enriching scene {i}/{n}…")
                    out.append(
                        await asyncio.to_thread(
                            _ollama_expand_one,
                            self.valves.OLLAMA_URL,
                            self.valves.PROMPT_LLM,
                            sc,
                        )
                    )
                shots = out
            else:
                await status(
                    f"📝 Using your {n} scenes verbatim (shot-splitter LLM off)…"
                )
        else:
            # freeform: strip control tokens, then let the LLM auto-split into n shots
            scene = re.sub(r"\b\d+\s*-?\s*(?:shot|scene)s?\b", "", scene)
            scene = re.sub(r"\b\d+(?:\.\d+)?\s*(?:s\b|sec\b|seconds?\b)", "", scene)
            scene = re.sub(
                r"\b(stills? only|images only|no video)\b",
                "",
                scene,
                flags=re.IGNORECASE,
            )
            scene = re.sub(
                r"\b(expand|enrich|enhance)\b", "", scene, flags=re.IGNORECASE
            )
            scene = re.sub(r"\s{2,}", " ", scene).strip(" ,.-")
            await status(f"🧠 Splitting the scene into {n} shots…")
            shots = []
            try:
                shots = await asyncio.to_thread(
                    _ollama_shots,
                    self.valves.OLLAMA_URL,
                    self.valves.PROMPT_LLM,
                    scene,
                    n,
                )
            except Exception:
                shots = []
            if not shots:
                base = [
                    f"wide establishing shot of {scene}, cinematic lighting",
                    f"medium shot, main subject of {scene}, detailed, dramatic light",
                    f"close-up on the key detail of {scene}, shallow depth of field",
                    f"over-the-shoulder shot within {scene}, moody atmosphere",
                    f"low-angle action shot of {scene}, dynamic composition",
                    f"aerial view of {scene}, sweeping scale",
                    f"slow tracking shot through {scene}, smooth steady glide",
                    f"final wide shot of {scene} at a different moment, cinematic mood",
                ]
                shots = (base * 2)[:n] if n > len(base) else base[: n - 1] + [base[-1]]
            shots = shots[:n]
            n = len(shots)

        passes = await self._ask_passes(ec)
        last = ""
        for p in range(1, passes + 1):
            if passes > 1 and ee:
                await ee(
                    {
                        "type": "message",
                        "data": {
                            "content": f"### 🎬 Generating video {p} of {passes}\n\n"
                        },
                    }
                )
            last = await self._render_shots(
                shots, n, secs, engine, stills_only, ee, user_id
            )
            if passes > 1 and p < passes and ee:
                await ee({"type": "message", "data": {"content": last + "\n\n---\n\n"}})
        return last

    async def _render_shots(
        self, shots, n, secs, engine, stills_only, ee, user_id=None
    ):
        """Render a ready-made list of shot prompts into stills or a stitched MP4.
        Shared by both the classic `_storyboard` path and the interactive wizard."""
        import asyncio

        async def status(desc, done=False):
            if ee:
                await ee(
                    {"type": "status", "data": {"description": desc, "done": done}}
                )

        async def emit(md):
            if ee:
                await ee({"type": "message", "data": {"content": md}})

        n = len(shots)

        # 0) echo the exact final selections before rendering (debugging aid) — shows the
        # actual prompts about to hit the model (post-expand if expand was used).
        _eng = "Wan 2.2 (quality)" if engine == "wan" else "LTX (fast)"
        _summary = "\n\n".join(
            f"**Scene {i}** ({len(s.split())}w): {s}" for i, s in enumerate(shots, 1)
        )
        _settings = f"{n} {'stills' if stills_only else 'scenes'}" + (
            "" if stills_only else f" × {secs:g}s each · {_eng}"
        )
        await emit(
            f"🎬 **OK — locked in.**\n\n{_summary}\n\n**Settings:** {_settings}\n\n🍞 **Baking now…**\n\n---\n\n"
        )

        # one shared seed per run: same seed + anchored prompts = consistent
        # character/look across every keyframe instead of 4 random strangers
        run_seed = uuid.uuid4().int % (2**31)

        # 2) classic stills mode (legacy behaviour, on request)
        if stills_only:
            ok = 0
            for i, shot in enumerate(shots, 1):
                await status(f"🎬 Shot {i}/{n} — rendering…")
                wf = wf_flux(
                    "flux1-schnell-fp8.safetensors",
                    shot,
                    "",
                    1024,
                    1024,
                    4,
                    run_seed,
                    None,
                )
                try:
                    img = await asyncio.to_thread(self._run, wf, "9", 320)
                    b64 = await asyncio.to_thread(self._fetch_b64, img)
                    ok += 1
                    await emit(
                        f"**🎬 Shot {i}/{n}** — *{shot}*\n\n![shot {i}](data:image/png;base64,{b64})\n\n"
                    )
                    try:
                        await asyncio.to_thread(
                            self._upload_image,
                            "data:image/png;base64," + b64,
                            "studio_last.png",
                        )
                    except Exception:
                        pass
                except Exception as e:
                    await emit(f"⚠️ Shot {i}/{n} failed: {e}\n\n")
            await status(f"✅ Storyboard done ({ok}/{n} stills)", True)
            return (
                f"🎬 **Storyboard complete** — {ok}/{n} stills rendered.\n\n"
                "To animate one: switch to **🎞️ Wan 2.2 (image → video)** and attach the shot "
                "(the last shot is already loaded — just type the motion you want)."
            )

        # 3) multi-shot VIDEO mode (default): each shot becomes a ~secs clip, stitched into one MP4
        def _wan_frames(s):
            return max(17, (int(s * 24) // 4) * 4 + 1)

        def _ltx_frames(s):
            return max(25, ((int(s * 25) - 1) // 8) * 8 + 1)

        tmp = tempfile.mkdtemp(prefix="sb_")
        run_id = uuid.uuid4().hex[:8]

        # keyframe stills anchor the look of each Wan clip (skipped for LTX t2v)
        stills = [None] * n
        if engine == "wan":
            for i, shot in enumerate(shots, 1):
                await status(f"🖼️ Keyframe {i}/{n}…")
                wf = wf_flux(
                    "flux1-schnell-fp8.safetensors",
                    shot,
                    "",
                    704,
                    480,
                    4,
                    run_seed,
                    None,
                )
                try:
                    img = await asyncio.to_thread(self._run, wf, "9", 320)
                    b64 = await asyncio.to_thread(self._fetch_b64, img)
                    stills[i - 1] = await asyncio.to_thread(
                        self._upload_image,
                        "data:image/png;base64," + b64,
                        f"sb_{run_id}_{i}.png",
                    )
                except Exception as e:
                    await emit(
                        f"⚠️ Keyframe {i}/{n} failed ({e}) — scene will render text→video.\n\n"
                    )

        clips, kept = [], []
        eng_label = "Wan 2.2" if engine == "wan" else "LTX"
        for i, shot in enumerate(shots, 1):
            frames = _wan_frames(secs) if engine == "wan" else _ltx_frames(secs)
            rendered = False
            for attempt in (1, 2):
                await status(
                    f"🎬 Scene {i}/{n} — {eng_label}, ~{secs:g}s clip"
                    + (" (retry, shorter)" if attempt == 2 else "")
                    + "…"
                )
                # pace guidance lives in the LLM shot instructions; stacking more
                # "slow/gentle/unhurried" here froze the clips into near-stills
                seed = (run_seed + i) % (2**31)
                if engine == "wan":
                    wf = wf_wan(
                        shot + ", smooth cinematic camera motion",
                        704,
                        480,
                        frames,
                        seed,
                        stills[i - 1],
                    )
                else:
                    wf = wf_ltx(
                        shot + ", smooth natural motion",
                        VIDEO_NEG,
                        768,
                        512,
                        frames,
                        seed,
                    )
                try:
                    outs = await asyncio.to_thread(self._run_full, wf, 900)
                    mp4 = outs.get("mp4", {}).get("images", [])
                    webp = outs.get("webp", {}).get("images", [])
                    if not mp4:
                        raise RuntimeError("no mp4 produced")
                    raw = await asyncio.to_thread(self._fetch_bytes_any, mp4[0])
                    cp = os.path.join(tmp, f"scene{i}.mp4")
                    with open(cp, "wb") as f:
                        f.write(raw)
                    clips.append(cp)
                    kept.append(shot)
                    await emit(f"**🎬 Scene {i}/{n}** rendered ✓\n\n> *{shot}*\n\n")
                    rendered = True
                    break
                except Exception as e:
                    if attempt == 1:
                        frames = (
                            _wan_frames(secs * 0.6)
                            if engine == "wan"
                            else _ltx_frames(secs * 0.6)
                        )
                        continue
                    await emit(f"⚠️ Scene {i}/{n} failed twice and was cut: {e}\n\n")
            if not rendered:
                continue
        if not clips:
            await status("Storyboard failed — no scenes survived", True)
            return "🎬 Storyboard failed: every scene errored. Check ComfyUI (`:8188`) and VRAM."

        # 4) stitch into one film
        await status(f"🎬 Stitching {len(clips)} scenes (ffmpeg)…")
        final = os.path.join(tmp, "storyboard.mp4")
        try:
            total = await asyncio.to_thread(
                self._assemble, clips, [None] * len(clips), final
            )
        except Exception as e:
            await status("Assembly failed", True)
            return f"🎬 Scenes rendered but stitching failed: {e}"
        with open(final, "rb") as f:
            data = f.read()
        url = await self._save_owui_file(data, f"storyboard_{run_id}.mp4", user_id)
        await status(
            f"✅ Storyboard video ready — {len(clips)} scenes, ~{total:.0f}s", True
        )

        shotlist = "\n\n".join(f"> **Scene {i}:** {s}" for i, s in enumerate(kept, 1))
        link = (
            f"\n\n### [🎬 ▶️ Watch the storyboard ({total:.0f}s, {len(data) // 1024}KB)]({url})"
            if url
            else "\n\n💾 OWUI file save failed — scene MP4s are in ComfyUI's `output/` folder."
        )
        return (
            f"🎬 **Storyboard complete** — {len(clips)}/{n} scenes × ~{secs:g}s, engine {eng_label}."
            f"\n\n{shotlist}{link}"
        )

