    def _kokoro_voices(self):
        """Live set of available Kokoro voice IDs (queried from the server), or a fallback set."""
        try:
            r = urllib.request.urlopen(
                self.valves.KOKORO_URL.rstrip("/") + "/v1/audio/voices", timeout=10
            )
            ids = {v.get("id") for v in json.load(r).get("voices", []) if v.get("id")}
            if ids:
                return ids
        except Exception:
            pass
        return {
            "af_heart",
            "af_bella",
            "af_nicole",
            "af_sarah",
            "af_sky",
            "am_adam",
            "am_michael",
            "am_liam",
            "bf_emma",
            "bf_alice",
            "bf_lily",
            "bm_george",
            "bm_lewis",
            "bm_daniel",
            "bm_fable",
        }

    def _tts(self, text, voice=None):
        """kokoro-tts -> mp3 bytes, or None on any failure (film falls back to silent)."""
        try:
            payload = {
                "model": "kokoro",
                "voice": (voice or self.valves.KOKORO_VOICE),
                "input": text,
                "response_format": "mp3",
            }
            req = urllib.request.Request(
                self.valves.KOKORO_URL.rstrip("/") + "/v1/audio/speech",
                data=json.dumps(payload).encode(),
                headers={"Content-Type": "application/json"},
            )
            return urllib.request.urlopen(req, timeout=120).read()
        except Exception:
            return None

    @staticmethod
    def _ffprobe_dur(path):
        r = subprocess.run(
            [
                "ffprobe",
                "-v",
                "error",
                "-show_entries",
                "format=duration",
                "-of",
                "csv=p=0",
                path,
            ],
            capture_output=True,
            text=True,
            timeout=60,
        )
        return float(r.stdout.strip())

    def _assemble(self, clips, audios, outpath):
        """Stitch clip MP4s + per-shot narration MP3s (None = silence) into one film."""
        n = len(clips)
        vd = [self._ffprobe_dur(c) for c in clips]
        ad = [self._ffprobe_dur(a) if a else 0.0 for a in audios]
        targets = [max(vd[i], ad[i] + 0.3) for i in range(n)]
        cmd = ["ffmpeg", "-y"]
        for c in clips:
            cmd += ["-i", c]
        for i, a in enumerate(audios):
            if a:
                cmd += ["-i", a]
            else:
                cmd += [
                    "-f",
                    "lavfi",
                    "-t",
                    f"{targets[i]:.2f}",
                    "-i",
                    "anullsrc=r=24000:cl=mono",
                ]
        parts = []
        for i in range(n):
            pad = max(0.0, targets[i] - vd[i])
            parts.append(
                f"[{i}:v]tpad=stop_mode=clone:stop_duration={pad:.2f},setsar=1[v{i}]"
            )
            parts.append(
                f"[{n + i}:a]aformat=sample_rates=24000:channel_layouts=mono,apad=whole_dur={targets[i]:.2f},atrim=0:{targets[i]:.2f}[a{i}]"
            )
        parts.append(
            "".join(f"[v{i}][a{i}]" for i in range(n)) + f"concat=n={n}:v=1:a=1[v][a]"
        )
        cmd += [
            "-filter_complex",
            ";".join(parts),
            "-map",
            "[v]",
            "-map",
            "[a]",
            "-c:v",
            "libx264",
            "-preset",
            "veryfast",
            "-crf",
            "20",
            "-pix_fmt",
            "yuv420p",
            "-r",
            "24",
            "-c:a",
            "aac",
            "-b:a",
            "128k",
            outpath,
        ]
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=600)
        if r.returncode != 0:
            raise RuntimeError("ffmpeg: " + (r.stderr or "")[-400:])
        return sum(targets)

    async def _save_owui_file(self, data, fname, user_id):
        """Store the film as a real file in the central generated-media folder
        (E:\\ai\\generated, served at /cache/generated/…). Falls back to OWUI's
        internal file storage if the central folder isn't mounted."""
        name, url = _central_save(data, os.path.splitext(fname)[0])
        if url:
            return url
        try:
            import inspect
            import io as _io
            from open_webui.models.files import Files, FileForm
            from open_webui.storage.provider import Storage

            fid = str(uuid.uuid4())
            try:
                _c, path = Storage.upload_file(
                    _io.BytesIO(data), f"{fid}_{fname}", tags={}
                )
            except TypeError:
                _c, path = Storage.upload_file(_io.BytesIO(data), f"{fid}_{fname}")
            r = Files.insert_new_file(
                user_id,
                FileForm(
                    id=fid,
                    filename=fname,
                    path=path,
                    meta={
                        "name": fname,
                        "content_type": "video/mp4",
                        "size": len(data),
                    },
                ),
            )
            if inspect.iscoroutine(r):
                r = await r
            if r is None:
                return None
            return f"/api/v1/files/{fid}/content"
        except Exception:
            return None

    async def _directors_cut(
        self, scene, ee, user_id, producer=False, ec=None, messages=None
    ):
        import asyncio

        async def status(desc, done=False):
            if ee:
                await ee(
                    {"type": "status", "data": {"description": desc, "done": done}}
                )

        async def emit(md):
            if ee:
                await ee({"type": "message", "data": {"content": md}})

        if not scene or (scene or "").strip().lower() in (
            "hello",
            "hi",
            "help",
            "?",
            "commands",
            "menu",
        ):
            return (
                "🍿 **Director's Cut — command reference**\n\n"
                "Describe a scene or story and I'll make a narrated short film "
                + (
                    "(Producer mode: paste a story of ANY length — a big model adapts it to fit).\n\n"
                    if producer
                    else "(the screenwriter LLM splits it into shots + voiceover).\n\n"
                )
                + "| Token | Effect |\n|---|---|\n"
                "| `a 3-shot film about…` | Shot count (2–6) |\n"
                "| `voice:bm_george` | Narrator voice (UK picks: `bm_george`, `bm_lewis`, `bf_emma`, `bf_alice`) |\n"
                + (
                    "| `fast` / `no-think` | Skip the producer's deep-reasoning pass (much quicker) |\n"
                    if producer
                    else ""
                )
                + "| `Scene 1: … Scene 2: …` | Your wording used **verbatim** (screenwriter OFF, narration still auto-written) |\n"
                "| `begin` / `begin 4s 3-shot` | Nothing renders until you send `begin` (+ optional tokens) |\n"
                "| `begin 4s` | Seconds per shot (1–8) |\n"
                "\nFlow: describe the story → check the plan menu → `begin [tokens]` → pick passes (1–4) — "
                "each pass is a complete separate film with fresh seeds.\n\n"
                "Engine is Wan 2.2 i2v, stitched + narrated (Kokoro TTS)."
            )

        def _msg_text(c):
            if isinstance(c, str):
                return c
            if isinstance(c, list):
                return " ".join(
                    x.get("text", "")
                    for x in c
                    if isinstance(x, dict) and x.get("type") == "text"
                ).strip()
            return ""

        # ---- begin gate (same UX as Storyboard): nothing renders until `begin [tokens]` ----
        is_begin = bool(
            re.match(r"^\s*(begin|start|render|go)\b", scene.strip().lower())
        )
        begin_line = ""
        if is_begin:
            begin_line = scene
            scene = ""
            for m in reversed((messages or [])[:-1]):
                if m.get("role") != "user":
                    continue
                txt = _msg_text(m.get("content")).strip()
                if txt and not re.match(r"^\s*(begin|start|render|go)\b", txt.lower()):
                    scene = txt
                    break
            if not scene:
                return "🍿 I don't have a story yet — describe it first, then send `begin`."

        combo = (scene + " " + begin_line).lower()

        nm = re.search(r"(\d+)\s*-?\s*shot", combo)
        n = (
            max(2, min(6, int(nm.group(1))))
            if nm
            else max(2, min(6, int(self.valves.FILM_SHOTS)))
        )

        sm = re.search(r"(\d+(?:\.\d+)?)\s*(?:s\b|sec\b|second)", combo)
        secs = (
            max(1.0, min(8.0, float(sm.group(1))))
            if sm
            else max(1.0, min(8.0, float(self.valves.FILM_SECONDS)))
        )
        frames = max(17, (int(secs * 24) // 4) * 4 + 1)

        # optional `voice:<name>` token (e.g. voice:bm_george) — overrides the KOKORO_VOICE valve
        vm = re.search(
            r"\bvoice\s*[:=]\s*([a-z]{2}_[a-z0-9]+)",
            scene + " " + begin_line,
            flags=re.IGNORECASE,
        )
        requested_voice = vm.group(1).lower() if vm else None
        voice = requested_voice or (self.valves.KOKORO_VOICE or "af_heart")
        scene = re.sub(
            r"\bvoice\s*[:=]\s*[a-z]{2}_[a-z0-9]+", "", scene, flags=re.IGNORECASE
        )

        fast = bool(re.search(r"\b(fast|no[\s-]?think|quick)\b", combo))
        scene = re.sub(
            r"\b(fast|no[\s-]?think|quick)\b", "", scene, flags=re.IGNORECASE
        )
        scene = re.sub(r"\s{2,}", " ", scene).strip(" ,.-")

        marked = _split_marked_scenes(scene)
        if marked:
            n = max(2, min(6, len(marked)))

        # ---- plan menu: shown for a plain story message; render only on `begin` ----
        if not is_begin and self.valves.FILM_CONFIRM:
            if marked:
                block = "\n".join(
                    f"> **Shot {i}:** {s.strip()}" for i, s in enumerate(marked[:6], 1)
                )
                mode = "your wording **verbatim** (screenwriter OFF · narration auto-written)"
            else:
                who = "Producer" if producer else "screenwriter"
                block = (
                    f"*{scene[:400]}*\n\n_No `Scene N:` markers — the {who} LLM will adapt this into "
                    f"{n} shots + narration. Add `Scene 1:` / `Scene 2:` markers to use your exact wording._"
                )
                mode = (
                    f"Producer LLM adapt ({'fast' if fast else 'deep reasoning'})"
                    if producer
                    else "screenwriter LLM"
                )
            est = int(n * (25 * secs + 40) + 60)
            return (
                f"🍿 **Director's Cut — ready when you are**\n\n{block}\n\n"
                f"**Plan:** {n} shots × {secs:g}s · Wan 2.2 i2v · narrator `{voice}` · {mode} · "
                f"est. ~{max(1, est // 60)} min per pass\n\n"
                "| Command | Effect |\n|---|---|\n"
                "| `begin` | ▶️ Render exactly as planned |\n"
                "| `begin 4s` | Seconds per shot (1–8) |\n"
                "| `begin 3-shot` | Shot count (2–6) |\n"
                "| `begin voice:bm_george` | Narrator voice |\n"
                + (
                    "| `begin fast` | Skip the producer's deep-reasoning pass |\n"
                    if producer
                    else ""
                )
                + "\nCommands combine — e.g. `begin 4s 3-shot voice:bm_george`. "
                "Send a new description to replace the story. "
                "*(Menu off via the `FILM_CONFIRM` valve.)*"
            )

        # validate the voice against the LIVE Kokoro list — warn + fall back instead of silent narration
        _avail = await asyncio.to_thread(self._kokoro_voices)
        if voice not in _avail:
            _fb = (
                self.valves.KOKORO_VOICE
                if self.valves.KOKORO_VOICE in _avail
                else "af_heart"
            )
            if _fb not in _avail:
                _fb = next(iter(sorted(_avail)), "af_heart")
            await emit(
                f"⚠️ Voice `{voice}` isn't installed on Kokoro — using `{_fb}` instead. "
                f"Valid UK picks: `bm_george`, `bm_lewis`, `bf_emma`, `bf_alice`.\n\n"
            )
            voice = _fb

        # 1) screenplay
        shots, vos = [], []
        if marked:
            # user's `Scene N:` wording used VERBATIM — screenwriter stays OFF;
            # the LLM only writes the voiceover lines
            shots = [s.strip() for s in marked][:6]
            vos = [""] * len(shots)
            await status("🎙️ Writing narration for your scenes…")
            try:
                instr2 = (
                    "Write one short voiceover sentence (max 18 words) for EACH numbered shot of a short film, "
                    "flowing as continuous narration. Output ONLY the sentences, one per line, no numbering.\n\n"
                    + "\n".join(f"{i}. {s}" for i, s in enumerate(shots, 1))
                )
                raw = await asyncio.to_thread(
                    _ollama_gen,
                    self.valves.OLLAMA_URL,
                    self.valves.PROMPT_LLM,
                    instr2,
                    timeout=120,
                )
                lines = [
                    l.strip().strip('"').lstrip("0123456789.)- ").strip()
                    for l in raw.splitlines()
                    if l.strip()
                ]
                vos = (lines + [""] * len(shots))[: len(shots)]
            except Exception:
                pass
        if producer and not shots:
            # big-model PRODUCER pass: adapt an arbitrary-length story to fit the film's limits
            pm = self.valves.FILM_PRODUCER_LLM
            maxn = max(2, min(6, int(nm.group(1)))) if nm else 6
            think = not fast
            if think:
                await status(
                    f"🎬 Producer ({pm}) adapting your story — deep reasoning "
                    f"(usually ~1–3 min; add `fast` to skip the thinking)…"
                )
            else:
                await status(
                    f"🎬 Producer ({pm}) adapting your story to fit (fast direct mode)…"
                )
            try:
                shots, vos = await asyncio.to_thread(
                    _ollama_produce, self.valves.OLLAMA_URL, pm, scene, maxn, 5.0, think
                )
            except Exception:
                shots, vos = [], []
            if shots:
                await emit(
                    f"🎬 **Producer's cut** — `{pm}` adapted your story into {len(shots)} shot(s).\n\n"
                )
            else:
                await emit(
                    f"⚠️ Producer model `{pm}` returned nothing — is it pulled? "
                    f"(`ollama pull {pm}`). Falling back to the standard `{self.valves.PROMPT_LLM}` screenwriter.\n\n"
                )
        if not shots:
            await status("🧠 Writing the screenplay…")
            try:
                shots, vos = await asyncio.to_thread(
                    _ollama_film,
                    self.valves.OLLAMA_URL,
                    self.valves.PROMPT_LLM,
                    scene,
                    n,
                )
            except Exception:
                pass
        if len(shots) < 2:
            shots = [
                f"wide establishing shot of {scene}, cinematic lighting",
                f"medium shot of the main subject of {scene}, dramatic light",
                f"close-up on the key detail of {scene}, shallow depth of field",
                f"closing wide shot of {scene}, changed mood, cinematic",
            ][: max(2, n)]
            vos = [""] * len(shots)
        n = len(shots)

        passes = await self._ask_passes(ec)

        async def _one_film():
            vos_local = list(vos)
            tmp = tempfile.mkdtemp(prefix="film_")
            run_id = uuid.uuid4().hex[:8]
            clips = []

            # one shared seed per film (fresh per pass): same seed + anchored prompts
            # keeps the main character consistent across every still
            run_seed = uuid.uuid4().int % (2**31)

            # 2) stills (all schnell first — avoids model swapping)
            stills = []
            for i, shot in enumerate(shots, 1):
                await status(f"🖼️ Still {i}/{n}…")
                wf = wf_flux(
                    "flux1-schnell-fp8.safetensors",
                    shot,
                    "",
                    704,
                    480,
                    4,
                    run_seed,
                    None,
                )
                img = await asyncio.to_thread(self._run, wf, "9", 320)
                b64 = await asyncio.to_thread(self._fetch_b64, img)
                name = await asyncio.to_thread(
                    self._upload_image,
                    "data:image/png;base64," + b64,
                    f"film_{run_id}_{i}.png",
                )
                stills.append(name)

            # 3) animate each still with Wan i2v
            for i, (shot, still) in enumerate(zip(shots, stills), 1):
                await status(
                    f"🎞️ Animating shot {i}/{n} (Wan 2.2 — takes a minute or two)…"
                )
                # pace guidance lives in the screenplay LLM instructions; stacking more
                # "slow/gentle/unhurried" here froze shots into near-stills
                seed = (run_seed + i) % (2**31)
                wf = wf_wan(
                    shot + ", smooth cinematic camera motion",
                    704,
                    480,
                    frames,
                    seed,
                    still,
                )
                try:
                    outs = await asyncio.to_thread(self._run_full, wf, 600)
                    mp4 = outs.get("mp4", {}).get("images", [])
                    if not mp4:
                        raise RuntimeError("no mp4 produced")
                    raw = await asyncio.to_thread(self._fetch_bytes_any, mp4[0])
                    pth = os.path.join(tmp, f"clip{i}.mp4")
                    with open(pth, "wb") as f:
                        f.write(raw)
                    clips.append(pth)
                    await emit(f"**🎞️ Shot {i}/{n}** rendered ✓\n\n> *{shot}*\n\n")
                except Exception as e:
                    await emit(
                        f"⚠️ Shot {i}/{n} failed and was cut from the film: {e}\n\n"
                    )
            if not clips:
                await status("Film failed — no shots survived", True)
                return "🍿 Film failed: every shot errored. Check ComfyUI logs."
            vos_local = vos_local[: len(clips)] + [""] * (len(clips) - len(vos_local))

            # 4) narration
            await status("🎙️ Recording narration (kokoro)…")
            audios = []
            for i, vo in enumerate(vos_local, 1):
                a = None
                if vo.strip():
                    mp3 = await asyncio.to_thread(self._tts, vo.strip(), voice)
                    if mp3:
                        a = os.path.join(tmp, f"vo{i}.mp3")
                        with open(a, "wb") as f:
                            f.write(mp3)
                audios.append(a)
            narrated = any(audios)

            # 5) assembly
            await status("🎬 Final cut (ffmpeg)…")
            final = os.path.join(tmp, "film.mp4")
            try:
                total = await asyncio.to_thread(self._assemble, clips, audios, final)
            except Exception as e:
                await status("Assembly failed", True)
                return f"🍿 Shots rendered but assembly failed: {e}"
            with open(final, "rb") as f:
                data = f.read()
            url = await self._save_owui_file(
                data, f"directors_cut_{run_id}.mp4", user_id
            )
            await status(f"✅ Film ready — {len(clips)} shots, ~{total:.0f}s", True)

            script = "\n\n".join(
                f"> **Shot {i}:** {s}" + (f'\n> 🎙️ *"{v}"*' if v else "")
                for i, (s, v) in enumerate(zip(shots, vos_local), 1)
            )
            link = (
                f"\n\n### [🍿 ▶️ Watch the film ({total:.0f}s, {len(data) // 1024}KB)]({url})"
                if url
                else "\n\n💾 Saved as `film.mp4` shots in the ComfyUI output folder (OWUI file save failed)."
            )
            return (
                f"🍿 **Director's Cut complete** — {len(clips)} shots, ~{total:.0f}s, "
                f"{'narrated by ' + voice if narrated else 'silent film'}.\n\n{script}{link}"
            )

        last = ""
        for p in range(1, passes + 1):
            if passes > 1 and ee:
                await ee(
                    {
                        "type": "message",
                        "data": {
                            "content": f"### 🍿 Generating film {p} of {passes}\n\n"
                        },
                    }
                )
            last = await _one_film()
            if passes > 1 and p < passes and ee:
                await ee({"type": "message", "data": {"content": last + "\n\n---\n\n"}})
        return last

    def _fetch_bytes_any(self, img):
        q = urllib.parse.urlencode(
            {
                "filename": img["filename"],
                "subfolder": img.get("subfolder", ""),
                "type": img.get("type", "output"),
            }
        )
        return urllib.request.urlopen(
            self.valves.COMFYUI_URL + "/view?" + q, timeout=300
        ).read()

    # ---- console (unchanged behaviour) --------------------------------------

    async def _console(self, ec, ee, neg):
        import asyncio

        if ec is None:
            return "⚠️ Open this in the OWUI chat window - the Console uses interactive popups."

        async def emit(md):
            if ee:
                await ee({"type": "message", "data": {"content": md}})

        async def ask(title, message, placeholder=""):
            return await ec(
                {
                    "type": "input",
                    "data": {
                        "title": title,
                        "message": message,
                        "placeholder": placeholder,
                    },
                }
            )

        # Step 1: pick LLM
        llms = []
        try:
            tags = await asyncio.to_thread(
                _get_json, self.valves.OLLAMA_URL.rstrip("/") + "/api/tags"
            )
            llms = sorted(
                [m.get("name") for m in tags.get("models", []) if m.get("name")]
            )
        except Exception:
            llms = []
        menu = "0: No LLM - use my exact words\n" + "\n".join(
            f"{i+1}: {n}" for i, n in enumerate(llms)
        )
        pick = (
            await ask(
                "Step 1 of 3 - prompt-writer LLM (type a number or part of a name)",
                menu,
                "e.g. 3  or  qwen3",
            )
            or ""
        ).strip()
        chosen_llm = None
        if pick.isdigit():
            k = int(pick)
            if 1 <= k <= len(llms):
                chosen_llm = llms[k - 1]
        elif pick:
            matches = [n for n in llms if pick.lower() in n.lower()]
            if matches:
                chosen_llm = matches[0]

        # Step 2: type the idea
        idea = await ask(
            "Step 2 of 3 - your idea",
            "Describe what you want. The LLM will expand it if you picked one.",
            "a corgi astronaut on mars",
        )
        idea = (idea or "").strip()
        if not idea:
            return "No prompt entered. Send `begin` to start again."

        # Step 3: pick image/video model
        menu2 = "\n".join(f"{i+1}: {lbl}" for i, (kk, lbl) in enumerate(IMAGE_MENU))
        ikey, ilabel = _pick_image(
            await ask(
                "Step 3 of 3 - image / video model (number or name)",
                menu2,
                "e.g. 3  or  chroma",
            ),
            IMAGE_MENU[0],
        )

        # build first job
        def enhance(text):
            if not chosen_llm:
                return text, ""
            try:
                e = _ollama_prompt(self.valves.OLLAMA_URL, chosen_llm, text)
                return e, f"🧠 *{chosen_llm} wrote:*\n> {e}\n\n"
            except Exception:
                return text, ""

        gen_prompt, note = enhance(idea)
        seed = uuid.uuid4().int % (2**31)
        wf, out_node, mime = build_image_wf(ikey, gen_prompt, neg, seed)
        last_b64, last_mime = None, "image/png"

        for _ in range(25):
            try:
                img = await asyncio.to_thread(self._run, wf, out_node, 320)
                last_b64 = await asyncio.to_thread(self._fetch_b64, img)
                last_mime = mime
            except Exception as e:
                await emit(f"⚠️ generation failed: {e}\n\n")
            else:
                await emit(
                    f"{note}**🎛️ {ilabel}** · seed `{seed}`\n\n![result](data:{mime};base64,{last_b64})\n\n"
                )
            note = ""
            nxt = await ask(
                "What next?",
                "1) 🔄 Regenerate (new seed)\n2) ✏️ Tweak the prompt\n3) 🎨 Different model\n4) 🔧 Refine this image (img2img)\n0) ✅ Done",
                "number",
            )
            c = str(nxt or "0").strip()
            seed = uuid.uuid4().int % (2**31)
            if c in ("0", "", "done"):
                break
            elif c == "1":
                wf, out_node, mime = build_image_wf(ikey, gen_prompt, neg, seed)
            elif c == "2":
                ni = (
                    await ask(
                        "Tweak the prompt", "Describe the new image.", gen_prompt[:60]
                    )
                    or ""
                ).strip()
                if ni:
                    gen_prompt, note = enhance(ni)
                wf, out_node, mime = build_image_wf(ikey, gen_prompt, neg, seed)
            elif c == "3":
                ikey, ilabel = _pick_image(
                    await ask(
                        "Pick a different model (number or name)",
                        menu2,
                        "e.g. 3  or  chroma",
                    ),
                    (ikey, ilabel),
                )
                wf, out_node, mime = build_image_wf(ikey, gen_prompt, neg, seed)
            elif c == "4":
                if not last_b64:
                    continue
                how = (
                    await ask(
                        "Refine this image",
                        "How should I restyle/change it?",
                        "make it an oil painting",
                    )
                    or ""
                ).strip()
                try:
                    name = await asyncio.to_thread(
                        self._upload_image, f"data:{last_mime};base64,{last_b64}"
                    )
                    wf = wf_img2img(
                        name, how or "high quality, highly detailed", neg, seed, 0.6
                    )
                    out_node, mime, ilabel = "9", "image/png", "img2img refine"
                except Exception as e:
                    await emit(f"⚠️ refine failed: {e}\n\n")
                    break
            else:
                break
        return "🎛️ *Console session ended — send* `begin` *to run it again.*"

