"""
title: Mermaid Modern Style
author: Liam Rooney
version: 1.0.0
license: MIT
description: Consistent flowchart styling after Mermaid Render Guard, with optional motion, hover tracing and faint authored groups.
"""
import json
import re
from collections import Counter, defaultdict
from typing import Optional
from pydantic import BaseModel, Field


class Filter:
    class Valves(BaseModel):
        priority: int = Field(default=10, description="Run after Mermaid Render Guard (priority 0).")
        enabled: bool = True
        animation: bool = True
        hover_trace: bool = True
        shadows: bool = True
        group_fill_opacity: float = Field(default=0.035, ge=0, le=0.2)

    FENCE = re.compile(r"(?P<open>```[ \t]*mermaid[ \t]*\r?\n)(?P<body>.*?)(?P<close>```)", re.I | re.S)
    HEADER = re.compile(r"^\s*(?:flowchart|graph)\s+(?:TB|TD|BT|RL|LR)\b", re.I)
    IDENTIFIER = r"[A-Za-z_][A-Za-z0-9_-]*"
    LABEL = r'"(?:\\.|[^"\\])*"'
    ENDPOINT = rf"(?P<{{name}}>{IDENTIFIER})(?:\[{LABEL}\]|\({LABEL}\)|\{{{LABEL}\}})?"
    EDGE = re.compile(rf"^\s*{ENDPOINT.replace('{name}', 'source')}\s*-->(?:\|[^|\r\n]*\|)?\s*{ENDPOINT.replace('{name}', 'target')}\s*;?\s*$")
    NODE = re.compile(rf'(?<![A-Za-z0-9_-])({IDENTIFIER})(?:\[{LABEL}\]|\({LABEL}\)|\{{{LABEL}\}})')
    MARKER = "%% owui-modern-style-v1"
    GUIDANCE = (
        "Mermaid presentation preference: retain the requested topology and diagram direction. "
        "When nodes share a clear semantic relationship, use a small labelled subgraph for that group, "
        "with at least two members. Do not invent extra causal claims or group unrelated nodes. "
        "Use short readable labels and quoted square nodes, one edge per line. "
        "The renderer supplies a consistent dark palette, font, corners, faint subgraphs, motion and hover effects; "
        "do not emit rainbow fills, low-contrast text, custom themeCSS or JavaScript callbacks. "
        "Optional semantic classes: owuiCause for inputs, owuiMechanism for mechanisms, owuiOutcome for outcomes, "
        "owuiWarning for caveats. Declare them using `class A,B owuiMechanism;` as appropriate. "
        "Group containers can slightly affect Mermaid's automatic layout; preserve relationships and overall orientation."
    )

    def __init__(self):
        self.valves = self.Valves()

    @classmethod
    def is_flowchart(cls, body):
        frontmatter = False
        for line in body.splitlines():
            stripped = line.strip()
            if stripped == "---":
                frontmatter = not frontmatter
                continue
            if frontmatter or not stripped or stripped.startswith("%%"):
                continue
            return bool(cls.HEADER.match(line))
        return False

    @classmethod
    def topology(cls, body):
        nodes = set()
        edges = []
        complete = True
        active = False
        for line in body.splitlines():
            stripped = line.strip()
            if not active:
                active = bool(cls.HEADER.match(line))
                continue
            if not stripped or stripped.startswith(("%%", "subgraph ", "style ", "class ", "classDef ", "linkStyle ", "click ")):
                continue
            nodes.update(cls.NODE.findall(line))
            edge = cls.EDGE.fullmatch(line)
            if edge:
                source, target = edge.group("source", "target")
                edges.append((source, target))
                nodes.update((source, target))
            elif re.search(r"-->|==>|-\.->|---|<--|~~~", line):
                complete = False
        if any(b.startswith(a + "-") for a in nodes for b in nodes if a != b):
            complete = False  # Avoid ambiguous prefix matches in Mermaid's generated SVG IDs.
        return nodes, edges, complete

    @staticmethod
    def reachable(node, edges, reverse=False):
        result = {node}
        queue = [node]
        while queue:
            current = queue.pop()
            for source, target in edges:
                if reverse:
                    source, target = target, source
                if source == current and target not in result:
                    result.add(target)
                    queue.append(target)
        return result

    def style_body(self, body):
        if (not self.valves.enabled or len(body) > 24000 or self.MARKER in body
            or "%% owui-modern:off" in body or "themeCSS" in body or not self.is_flowchart(body)):
            return body
        nodes, edges, complete = self.topology(body)
        incoming = Counter(target for _, target in edges)
        outgoing = Counter(source for source, _ in edges)
        convergence = {node for node in nodes if incoming[node] > 1} if complete else set()
        outcomes = {node for node in nodes if incoming[node] and not outgoing[node]} if complete else set()
        backbone = set()
        for node in convergence:
            backbone.update(self.reachable(node, edges))
        shape = ".node rect,.node circle,.node ellipse,.node polygon,.node path"
        css = [
            f"{shape}{{fill:#111827!important;fill-opacity:1!important;stroke:#475569!important;stroke-width:1.5px!important;}}",
            ".node rect{rx:16!important;ry:16!important;}",
            ".node .label text,.node .label tspan,.node .label span{fill:#F1F5F9!important;color:#F1F5F9!important;font-family:Segoe UI,Arial,sans-serif!important;font-weight:500!important;}",
            ".flowchart-link{stroke-linecap:round!important;stroke-linejoin:round!important;}",
            f".cluster rect{{fill:#CBD5E1!important;fill-opacity:{self.valves.group_fill_opacity}!important;stroke:#64748B!important;stroke-opacity:.45!important;stroke-width:1px!important;rx:18!important;ry:18!important;}}",
            ".cluster-label text,.cluster-label span{fill:#CBD5E1!important;color:#CBD5E1!important;font-family:Segoe UI,Arial,sans-serif!important;}.cluster-label text{paint-order:stroke;stroke:#111827;stroke-width:3px;stroke-linejoin:round;}",
            ".node,.flowchart-link{transition:opacity .12s ease;}",
            ".node:hover rect,.node:focus-within rect{stroke:#22D3EE!important;stroke-width:2.5px!important;}",
        ]
        if self.valves.shadows:
            css.append(".node rect,.node polygon{filter:drop-shadow(0 3px 4px #00000038);}")
        for ids, fill, stroke in ((convergence, "#083344", "#22D3EE"), (outcomes, "#2E1065", "#A78BFA")):
            for node in sorted(ids):
                css.append(f'.node[id*="flowchart-{node}-"] rect,.node[id*="flowchart-{node}-"] polygon{{fill:{fill}!important;stroke:{stroke}!important;stroke-width:2px!important;}}')
        # Explicit semantic classes take precedence over topology-based defaults.
        for category, fill, stroke in (("owuiCause", "#111827", "#475569"), ("owuiMechanism", "#083344", "#22D3EE"), ("owuiOutcome", "#2E1065", "#A78BFA"), ("owuiWarning", "#451A03", "#FBBF24")):
            css.append(f".node.{category} rect,.node.{category} polygon,.node.{category} circle{{fill:{fill}!important;stroke:{stroke}!important;stroke-width:2px!important;}}")
        pair_count = defaultdict(int)
        edge_ids = []
        main_indexes = []
        for index, (source, target) in enumerate(edges):
            count = pair_count[source, target]
            # Mermaid gives the first parallel edge counter 0 and later edges counters 2,3,...
            edge_id = f"L_{source}_{target}_{0 if count == 0 else count + 1}"
            pair_count[source, target] += 1
            edge_ids.append(edge_id)
            if complete and source in backbone:
                main_indexes.append(index)
                if self.valves.animation:
                    css.append(f'.flowchart-link[data-id="{edge_id}"]{{stroke-dasharray:10 6!important;animation:owuiModernFlow 4s linear infinite;}}')
        if self.valves.animation and main_indexes:
            css.append("@keyframes owuiModernFlow{to{stroke-dashoffset:-32;}}")
        if self.valves.hover_trace and complete and len(nodes) <= 24 and len(edges) <= 60:
            hover_css = []
            for node in sorted(nodes):
                related = self.reachable(node, edges) | self.reachable(node, edges, reverse=True)
                trigger = f'.root:has(.node[id*="flowchart-{node}-"]:hover)'
                excluded = "".join(f':not([id*="flowchart-{n}-"])' for n in sorted(related))
                hover_css.append(f"{trigger} .node{excluded}{{opacity:.22;}}")
                kept_edges = [edge_ids[i] for i, (a, b) in enumerate(edges) if a in related and b in related]
                excluded_edges = "".join(f':not([data-id="{edge_id}"])' for edge_id in kept_edges)
                hover_css.append(f"{trigger} .flowchart-link{excluded_edges}{{opacity:.18;}}")
            if sum(map(len, hover_css)) <= 10000:
                css.extend(hover_css)
        css.append("@media(prefers-reduced-motion:reduce){.flowchart-link{animation:none!important;stroke-dasharray:none!important;}.node,.flowchart-link{transition:none!important;}}")
        config = {"theme":"base", "fontFamily":"Segoe UI, Arial", "themeVariables":{"darkMode":True,"fontFamily":"Segoe UI, Arial","fontSize":"18px","primaryColor":"#111827","primaryTextColor":"#F1F5F9","primaryBorderColor":"#475569","lineColor":"#CBD5E1","edgeLabelBackground":"#111827"}, "themeCSS":"".join(css)}
        directive = "%%{init: " + json.dumps(config, separators=(",", ":")) + "}%%"
        additions = ["linkStyle default stroke:#CBD5E1,stroke-width:2.5px;"]
        if main_indexes:
            additions.append("linkStyle " + ",".join(map(str, main_indexes)) + " stroke:#22D3EE,stroke-width:3px;")
        for category in ("owuiCause", "owuiMechanism", "owuiOutcome", "owuiWarning"):
            additions.append(f"classDef {category} color:#F1F5F9;")
        roles = {}
        for line in body.splitlines():
            assignment = re.fullmatch(rf"\s*class\s+({self.IDENTIFIER}(?:\s*,\s*{self.IDENTIFIER})*)\s+(owuiCause|owuiMechanism|owuiOutcome|owuiWarning)\s*;?\s*", line)
            if assignment:
                roles.update({node.strip():assignment[2] for node in assignment[1].split(',')})
        palette = {"owuiCause":("#111827","#475569"),"owuiMechanism":("#083344","#22D3EE"),"owuiOutcome":("#2E1065","#A78BFA"),"owuiWarning":("#451A03","#FBBF24")}
        # Mermaid materialises authored styles as inline !important declarations.
        # Later native style statements are needed to replace their pastel fills too.
        for node in sorted(nodes):
            role = roles.get(node, "owuiOutcome" if node in outcomes else "owuiMechanism" if node in convergence else "owuiCause")
            fill, stroke = palette[role]
            width = "1.5" if role == "owuiCause" else "2"
            additions.append(f"style {node} fill:{fill},fill-opacity:1,stroke:{stroke},stroke-width:{width}px,color:#F1F5F9,font-size:18px,font-weight:500,rx:16,ry:16;")
        for line in body.splitlines():
            group = re.fullmatch(rf'\s*subgraph\s+({self.IDENTIFIER})(?:\s*\[{self.LABEL}\])?\s*', line)
            if group:
                additions.append(f"style {group[1]} fill:#CBD5E1,fill-opacity:{self.valves.group_fill_opacity},stroke:#64748B,stroke-opacity:0.45,stroke-width:1px,rx:18,ry:18;")
        newline = "\r\n" if "\r\n" in body else "\n"
        # Keep frontmatter first. Mermaid requires its YAML delimiters at the start.
        insertion = 0
        if body.lstrip().startswith("---"):
            lines = body.splitlines(keepends=True)
            delimiters = [i for i, line in enumerate(lines) if line.strip() == "---"]
            if len(delimiters) < 2:
                return body
            insertion = sum(len(line) for line in lines[:delimiters[1] + 1])
        prefix = directive + newline + self.MARKER + newline
        return body[:insertion] + prefix + body[insertion:].rstrip("\r\n") + newline + newline.join(additions) + newline

    def style_content(self, content):
        def style(match):
            return match.group("open") + self.style_body(match.group("body")) + match.group("close")
        return self.FENCE.sub(style, content)

    def stream(self, event: dict, __metadata__: Optional[dict] = None) -> dict:
        # Guard releases completed Mermaid fences as one frame; no second buffer is needed.
        if not self.valves.enabled:
            return event
        try:
            for choice in event.get("choices", []):
                delta = choice.get("delta", {})
                content = delta.get("content")
                if isinstance(content, str) and "```" in content:
                    delta["content"] = self.style_content(content)
        except Exception:
            pass
        return event

    async def inlet(self, body: dict, __user__: Optional[dict] = None) -> dict:
        messages = body.get("messages", [])
        latest = next((m.get("content", "") for m in reversed(messages) if m.get("role") == "user"), "")
        if self.valves.enabled and isinstance(latest, str) and re.search(r"\bmermaid\b|\bflowcharts?\b|\bdiagrams?\b", latest, re.I):
            at = 1 if messages and messages[0].get("role") == "system" else 0
            messages.insert(at, {"role":"system", "content":self.GUIDANCE})
        return body

    async def outlet(self, body: dict, __user__: Optional[dict] = None) -> dict:
        if self.valves.enabled:
            for message in reversed(body.get("messages", [])):
                if message.get("role") == "assistant":
                    content = message.get("content")
                    if isinstance(content, str):
                        message["content"] = self.style_content(content)
                    break
        return body

"""
title: Mermaid Render Guard
author: Liam Rooney
version: 1.2.0
license: MIT
description: Repairs a small, deterministic subset of flowchart syntax inside fenced Mermaid blocks, live during streaming and again on completion.
"""

import re
import time
from typing import Any, Optional

from pydantic import BaseModel, Field


class Filter:
    """Narrow Mermaid syntax guidance plus stream-time and completed-response repair.

    Why the stream hook exists (v1.2.0): the Open WebUI chat renderer draws a Mermaid
    block the moment its closing fence arrives in the stream, which is before outlet()
    runs. outlet() alone therefore fixed the saved message but not what Liam saw live.
    stream() holds each ```mermaid block back until it is complete, repairs it with the
    same repair_content() used by outlet(), and releases it in one piece.
    """

    class Valves(BaseModel):
        priority: int = Field(default=0, description="Filter order; lower runs first.")
        stream_buffering: bool = Field(
            default=True,
            description="Hold each streamed ```mermaid block until complete and release it repaired.",
        )
        max_buffer_chars: int = Field(
            default=24000,
            description="Safety cap: a single Mermaid block larger than this is released unrepaired.",
        )

    _MERMAID_REQUEST = re.compile(r"\bmermaid\b", re.IGNORECASE)
    _MERMAID_FENCE = re.compile(
        r"(?P<open>```[ \t]*mermaid[ \t]*\r?\n)(?P<body>.*?)(?P<close>```)",
        re.IGNORECASE | re.DOTALL,
    )
    # Stream-time fence detection.
    _STREAM_OPEN = re.compile(r"```[ \t]*mermaid[ \t]*\r?\n", re.IGNORECASE)
    # A trailing fragment that could still grow into a Mermaid opener: 1-3 backticks,
    # optional spaces, then a (possibly partial) "mermaid", optional spaces, optional \r.
    _PARTIAL_OPEN = re.compile(r"`{1,3}(?:[ \t]*[A-Za-z]{0,7}[ \t]*\r?)?$")
    _STREAM_STATE_TTL_SECONDS = 1800

    _SQUARE_NODE = re.compile(
        r"(?<![A-Za-z0-9_-])(?P<id>[A-Za-z_][A-Za-z0-9_-]*)\[(?P<label>[^\]\r\n]*)\]"
    )
    _FLOWCHART_HEADER = re.compile(
        r"^[ \t]*(?:flowchart|graph)[ \t]+(?:TB|TD|BT|RL|LR)\b", re.IGNORECASE
    )
    _EDGE_LINE = re.compile(
        r"^(?P<indent>[ \t]*)(?P<left>.+?)(?P<before>[ \t]+)-->(?P<after>[ \t]+)"
        r"(?P<right>.+?)(?P<semi>;?)(?P<trailing>[ \t]*)$"
    )
    _BARE_ID = re.compile(r"^[A-Za-z_][A-Za-z0-9_-]*$")
    _NODE_ENDPOINT = re.compile(
        r"^[A-Za-z_][A-Za-z0-9_-]*(?:\[[^\]\r\n]*\])?$"
    )
    _RESERVED_END = re.compile(
        r"(?<![A-Za-z0-9_-])end(?=[ \t]*(?:\[|-->|,|$))"
    )
    _GUIDANCE = (
        "Mermaid flowchart rendering rules: place every human-readable square-node label in double "
        'quotes, for example brain["Brain (hypothalamus)"]. Express fan-in or fan-out as one edge '
        "per line; do not write `A, B --> C` or `A --> B, C`. Do not use lowercase `end` as a node "
        "identifier. Prefer `flowchart` to the legacy `graph` alias."
    )

    def __init__(self) -> None:
        self.valves = self.Valves()
        # Per-stream buffering state, keyed by message id. The Filter instance is cached and
        # shared across concurrent chats, so state must never be kept in a single attribute.
        self._streams: dict[str, dict[str, Any]] = {}

    # ------------------------------------------------------------------ repair core

    @classmethod
    def _latest_user_text(cls, messages: list[dict[str, Any]]) -> str:
        for message in reversed(messages):
            if message.get("role") != "user":
                continue
            content = message.get("content", "")
            if isinstance(content, str):
                return content
            if isinstance(content, list):
                return "\n".join(
                    str(part.get("text", ""))
                    for part in content
                    if isinstance(part, dict) and part.get("type") in {"text", "input_text"}
                )
        return ""

    @staticmethod
    def _quote_square_label(match: re.Match[str]) -> str:
        node_id = match.group("id")
        label = match.group("label").strip()
        if not label or (len(label) >= 2 and label[0] == label[-1] == '"'):
            return match.group(0)
        safe_label = label.replace('"', "&quot;")
        return f'{node_id}["{safe_label}"]'

    @staticmethod
    def _line_ending(line: str) -> tuple[str, str]:
        if line.endswith("\r\n"):
            return line[:-2], "\r\n"
        if line.endswith("\n"):
            return line[:-1], "\n"
        return line, ""

    @classmethod
    def _is_flowchart(cls, body: str) -> bool:
        """Recognise only flowchart/graph blocks; leave other Mermaid grammars alone."""

        for line in body.splitlines():
            stripped = line.strip()
            if not stripped or stripped.startswith("%%"):
                continue
            return bool(cls._FLOWCHART_HEADER.match(line))
        return False

    @staticmethod
    def _split_top_level_commas(value: str) -> Optional[list[str]]:
        """Split commas outside quotes/brackets, or decline malformed/ambiguous input."""

        parts: list[str] = []
        start = 0
        quote: Optional[str] = None
        escaped = False
        stack: list[str] = []
        pairs = {"]": "[", ")": "(", "}": "{"}
        for index, char in enumerate(value):
            if quote is not None:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == quote:
                    quote = None
                continue
            if char in {'"', "'"}:
                quote = char
            elif char in "[({":
                stack.append(char)
            elif char in "])}":
                if not stack or stack.pop() != pairs[char]:
                    return None
            elif char == "," and not stack:
                part = value[start:index].strip()
                if not part:
                    return None
                parts.append(part)
                start = index + 1
        if quote is not None or stack:
            return None
        tail = value[start:].strip()
        if not tail:
            return None
        parts.append(tail)
        return parts

    @classmethod
    def _expand_comma_edge(cls, line: str) -> str:
        """Expand only plain `-->` fan-in/fan-out statements with unambiguous endpoints."""

        core, newline = cls._line_ending(line)
        if "%%" in core or "://" in core or cls._RESERVED_END.search(core):
            return line
        match = cls._EDGE_LINE.fullmatch(core)
        if match is None:
            return line

        left = cls._split_top_level_commas(match.group("left"))
        right = cls._split_top_level_commas(match.group("right"))
        if left is None or right is None:
            return line
        if len(left) > 1 and len(right) == 1:
            if not all(cls._BARE_ID.fullmatch(item) for item in left):
                return line
            if not cls._NODE_ENDPOINT.fullmatch(right[0]):
                return line
            edges = [(item, right[0]) for item in left]
        elif len(left) == 1 and len(right) > 1:
            if not cls._NODE_ENDPOINT.fullmatch(left[0]):
                return line
            if not all(cls._BARE_ID.fullmatch(item) for item in right):
                return line
            edges = [(left[0], item) for item in right]
        else:
            return line

        prefix = match.group("indent")
        separator = match.group("before") + "-->" + match.group("after")
        suffix = match.group("semi") + match.group("trailing")
        joiner = newline or "\n"
        return joiner.join(
            prefix + source + separator + target + suffix for source, target in edges
        ) + newline

    @classmethod
    def _repair_flowchart(cls, body: str) -> str:
        repaired_lines: list[str] = []
        for line in body.splitlines(keepends=True):
            core, newline = cls._line_ending(line)
            stripped = core.lstrip()
            protected = (
                not stripped
                or stripped.startswith("%%")
                or stripped.lower().startswith("click ")
                or "://" in core
                or cls._RESERVED_END.search(core)
            )
            quoted = core if protected else cls._SQUARE_NODE.sub(cls._quote_square_label, core)
            repaired_lines.append(cls._expand_comma_edge(quoted + newline))
        return "".join(repaired_lines)

    @classmethod
    def repair_content(cls, content: str) -> str:
        """Repair only recognised flowcharts inside completed Mermaid fences."""

        def repair_fence(match: re.Match[str]) -> str:
            body = match.group("body")
            repaired = cls._repair_flowchart(body) if cls._is_flowchart(body) else body
            return match.group("open") + repaired + match.group("close")

        return cls._MERMAID_FENCE.sub(repair_fence, content)

    # ------------------------------------------------------------------ stream buffering

    def _process_stream_text(self, state: dict[str, Any], text: str) -> str:
        """Feed streamed text in; return the text that is safe to release now.

        Outside a Mermaid block, text is released immediately except for a short trailing
        fragment that could still become a ```mermaid opener. Inside a block, everything is
        held until the closing fence arrives, then the whole block is repaired and released.
        """

        pending = state["pending"] + text
        released: list[str] = []
        while True:
            if not state["in_fence"]:
                opener = self._STREAM_OPEN.search(pending)
                if opener is not None:
                    released.append(pending[: opener.start()])
                    pending = pending[opener.start():]
                    state["in_fence"] = True
                    state["open_len"] = opener.end() - opener.start()
                    continue
                partial = self._PARTIAL_OPEN.search(pending)
                if partial is not None and self._could_become_opener(pending[partial.start():]):
                    released.append(pending[: partial.start()])
                    pending = pending[partial.start():]
                else:
                    released.append(pending)
                    pending = ""
                break

            close = pending.find("```", state["open_len"])
            if close != -1:
                block = pending[: close + 3]
                released.append(self.repair_content(block))
                pending = pending[close + 3:]
                state["in_fence"] = False
                state["open_len"] = 0
                continue
            if len(pending) > max(1000, int(self.valves.max_buffer_chars)):
                # Runaway or unterminated block: stop holding it back. The remainder of this
                # block streams raw and outlet() still repairs the saved copy.
                released.append(pending)
                pending = ""
                state["in_fence"] = False
                state["open_len"] = 0
                state["passthrough"] = True
            break

        state["pending"] = pending
        return "".join(released)

    @staticmethod
    def _could_become_opener(fragment: str) -> bool:
        stripped = fragment.lstrip("`")
        ticks = len(fragment) - len(stripped)
        if ticks == 0 or ticks > 3:
            return False
        word = stripped.strip(" \t\r").lower()
        if ticks < 3:
            return word == ""
        return "mermaid".startswith(word)

    def _stream_key(self, event: dict, metadata: Optional[dict]) -> str:
        if isinstance(metadata, dict):
            for field in ("message_id", "chat_id"):
                value = metadata.get(field)
                if value:
                    return f"{field}:{value}"
        event_id = event.get("id") if isinstance(event, dict) else None
        return f"event:{event_id}" if event_id else "default"

    def _prune_streams(self, now: float) -> None:
        stale = [
            key
            for key, state in self._streams.items()
            if now - state.get("touched", now) > self._STREAM_STATE_TTL_SECONDS
        ]
        for key in stale:
            self._streams.pop(key, None)

    def stream(self, event: dict, __metadata__: Optional[dict] = None) -> dict:
        try:
            if not getattr(self.valves, "stream_buffering", True) or not isinstance(event, dict):
                return event
            choices = event.get("choices")
            if not isinstance(choices, list) or not choices or not isinstance(choices[0], dict):
                return event
            choice = choices[0]
            delta = choice.get("delta")
            finish_reason = choice.get("finish_reason")
            text = delta.get("content") if isinstance(delta, dict) else None

            key = self._stream_key(event, __metadata__)
            state = self._streams.get(key)
            if state is None:
                if not isinstance(text, str) or "`" not in text:
                    return event  # Fast path: nothing pending and no backtick in this chunk.
                now = time.time()
                self._prune_streams(now)
                state = {"pending": "", "in_fence": False, "open_len": 0, "touched": now}
                self._streams[key] = state
            state["touched"] = time.time()

            out = self._process_stream_text(state, text) if isinstance(text, str) else ""
            if finish_reason:
                out += state["pending"]
                self._streams.pop(key, None)
            elif not state["pending"] and not state["in_fence"]:
                self._streams.pop(key, None)

            if isinstance(text, str) or out:
                if not isinstance(delta, dict):
                    delta = {}
                    choice["delta"] = delta
                delta["content"] = out
            return event
        except Exception:
            # Never break a chat because of the guard: fail open to the unmodified event.
            return event

    # ------------------------------------------------------------------ inlet / outlet

    async def inlet(self, body: dict, __user__: Optional[dict] = None) -> dict:
        messages = body.get("messages")
        if not isinstance(messages, list) or not self._MERMAID_REQUEST.search(self._latest_user_text(messages)):
            return body

        guidance_message = {"role": "system", "content": self._GUIDANCE}
        insert_at = 1 if messages and messages[0].get("role") == "system" else 0
        messages.insert(insert_at, guidance_message)
        return body

    async def outlet(self, body: dict, __user__: Optional[dict] = None) -> dict:
        messages = body.get("messages")
        if not isinstance(messages, list):
            return body

        for message in reversed(messages):
            if message.get("role") != "assistant":
                continue
            content = message.get("content")
            if isinstance(content, str) and "```" in content and self._MERMAID_REQUEST.search(content):
                message["content"] = self.repair_content(content)
            break
        return body
